ALTER TABLE public.workspaces ADD COLUMN regional_profile jsonb;
ALTER TABLE public.user_profiles ADD COLUMN regional_profile jsonb;
ALTER TABLE public.vehicles ADD COLUMN regional_service_areas jsonb;
CREATE FUNCTION public.validate_regional_profile_value(_value jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE a jsonb; BEGIN IF _value IS NULL THEN RETURN true; END IF; IF jsonb_typeof(_value->'areas') IS DISTINCT FROM 'array' OR jsonb_array_length(_value->'areas')>100 OR jsonb_typeof(_value->'crossState') IS DISTINCT FROM 'boolean' THEN RETURN false; END IF; IF _value->>'radius' IS NOT NULL AND ((_value->>'radius')::numeric NOT BETWEEN 1 AND 200 OR (_value->>'radius')::numeric<>trunc((_value->>'radius')::numeric)) THEN RETURN false; END IF; FOR a IN SELECT value FROM jsonb_array_elements(_value->'areas') LOOP IF a->>'country' IS DISTINCT FROM 'US' OR NOT public.us_state_catalog() ? coalesce(a->>'state','') OR coalesce(a->>'evidence','') NOT IN ('provider_entered','user_selected','generalized','approximate','unverified') OR coalesce(a->>'countyType','') NOT IN ('county','parish','borough','census_area','independent_city','municipality','district','other') OR length(coalesce(a->>'countyEquivalent',''))>120 OR length(coalesce(a->>'locality',''))>100 OR (coalesce(a->>'postalCode','')<>'' AND a->>'postalCode' !~ '^\d{5}(-\d{4})?$') OR (coalesce(a->>'timezone','')<>'' AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=a->>'timezone')) OR (coalesce(a->>'region','')<>'' AND (a->>'state'<>'FL' OR a->>'region' NOT IN ('panhandle','northeast','north-central','central','tampa-bay','southwest','southeast'))) THEN RETURN false; END IF; END LOOP; RETURN true; EXCEPTION WHEN OTHERS THEN RETURN false; END $$;
CREATE FUNCTION public.regional_private_value_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v jsonb; BEGIN v:=CASE WHEN TG_TABLE_NAME IN ('workspaces','user_profiles') THEN to_jsonb(NEW)->'regional_profile' ELSE to_jsonb(NEW)->'regional_service_areas' END; IF v='null'::jsonb THEN v:=NULL; END IF; IF NOT public.validate_regional_profile_value(v) THEN RAISE EXCEPTION 'Review supported state, ZIP, region, radius and IANA timezone'; END IF; RETURN NEW; END $$;
CREATE TRIGGER regional_workspace_profile BEFORE INSERT OR UPDATE OF regional_profile ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.regional_private_value_guard();
CREATE TRIGGER regional_person_profile BEFORE INSERT OR UPDATE OF regional_profile ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION public.regional_private_value_guard();
CREATE TRIGGER regional_driver_boundaries BEFORE INSERT OR UPDATE OF regional_service_areas ON public.drivers FOR EACH ROW EXECUTE FUNCTION public.regional_private_value_guard();
CREATE TRIGGER regional_vehicle_boundaries BEFORE INSERT OR UPDATE OF regional_service_areas ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.regional_private_value_guard();
CREATE FUNCTION public.private_regional_profile(_kind text,_id uuid,_value jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; ws uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _value IS NOT NULL AND NOT public.validate_regional_profile_value(_value) THEN RAISE EXCEPTION 'Regional values require review'; END IF; IF _kind='person' THEN IF _id<>auth.uid() THEN RAISE EXCEPTION 'Own profile required'; END IF; IF _value IS NOT NULL THEN UPDATE public.user_profiles SET regional_profile=_value WHERE user_id=_id AND status='active' AND NOT is_test_account AND deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Profile unavailable'; END IF; END IF; SELECT regional_profile INTO result FROM public.user_profiles WHERE user_id=_id AND status='active' AND NOT is_test_account AND deleted_at IS NULL; ELSIF _kind='workspace' THEN ws:=_id; IF NOT public.can_manage_account_connections(ws) THEN RAISE EXCEPTION 'Authorized account manager required'; END IF; IF _value IS NOT NULL THEN UPDATE public.workspaces SET regional_profile=_value WHERE id=ws AND status='active' AND NOT is_test_account; IF NOT FOUND THEN RAISE EXCEPTION 'Account unavailable'; END IF; END IF; SELECT regional_profile INTO result FROM public.workspaces WHERE id=ws AND status='active' AND NOT is_test_account; ELSE RAISE EXCEPTION 'Unsupported regional profile'; END IF; IF _value IS NOT NULL THEN IF result IS DISTINCT FROM _value THEN RAISE EXCEPTION 'Regional persistence readback failed'; END IF; INSERT INTO public.account_security_audit(user_id,event_type,result,details) VALUES(auth.uid(),'private_regional_profile','saved',jsonb_build_object('kind',_kind,'workspace_id',ws,'fields','regional_profile')); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.private_regional_profile(text,uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.private_regional_profile(text,uuid,jsonb) TO authenticated;
COMMENT ON COLUMN public.workspaces.regional_profile IS 'Private owner-entered profile; never public visibility or eligibility evidence.';
COMMENT ON COLUMN public.vehicles.regional_service_areas IS 'Optional scoped boundaries, not verification, enrollment or automatic matching.';